import os
import glob
import json
from stages.cctf import recover_committed


def replay_dead_letters(recovered_dir: str, dlq_dir: str, config: dict) -> tuple:
    records = {}
    order = []
    for path in sorted(glob.glob(os.path.join(recovered_dir, "recovered_*.json"))):
        with open(path) as f:
            for r in json.load(f):
                tid = r.get("transaction_id")
                if tid not in records:
                    order.append(tid)
                records[tid] = r
    lock = config["lock_timeout_sec"]
    integrated = 0
    discarded = 0
    for path in sorted(glob.glob(os.path.join(dlq_dir, "dlq_*.cctf"))):
        with open(path, "rb") as f:
            data = f.read()
        for r in recover_committed(data, config):
            tid = r.get("transaction_id")
            if tid not in records:
                records[tid] = r
                order.append(tid)
                integrated += 1
            else:
                drift = abs(r.get("timestamp", 0) - records[tid].get("timestamp", 0))
                if drift <= lock:
                    discarded += 1
                else:
                    records[tid] = r
                    integrated += 1
    combined = [records[t] for t in order]
    audit = {"integrated_dlq_records": integrated,
             "discarded_duplicates": discarded}
    return combined, audit
